SELECT id, phone, password_hash, nickname, role, health_profile, created_at, updated_at
FROM user
WHERE phone = #{phone}

SELECT id, phone, password_hash, nickname, role, health_profile, created_at, updated_at
FROM user
WHERE id = #{id}

SELECT COUNT(*)
FROM user
WHERE role = #{role}
  AND last_active_at IS NOT NULL
  AND last_active_at >= #{since}
